using System.Text.Json;using Microsoft.EntityFrameworkCore;using SenorArroz.Application.Common.Interfaces;using SenorArroz.Application.Common.Models;using SenorArroz.Domain.Enums;using SenorArroz.Domain.Services;using SenorArroz.Infrastructure.Data;
namespace SenorArroz.Infrastructure.Services;
public class RequestHumanAssistanceAgentTool(ApplicationDbContext db,WhatsAppAttentionService attention,IWhatsAppNotificationService notifications,IWhatsAppAutomaticMessageSender sender,IClock clock):IAgentTool
{
 public string Name=>"request_human_assistance";public string Description=>"Transfiere de forma terminal la conversación a un asesor cuando el cliente lo solicita o el caso no puede resolverse.";public string Category=>"attention";public bool ModifiesData=>true;public string RiskLevel=>"high";public JsonElement ParametersSchema=>JsonDocument.Parse("""{"type":"object","properties":{"reason":{"type":"string","maxLength":500}},"required":["reason"],"additionalProperties":false}""").RootElement.Clone();
 public async Task<AgentToolExecutionResult> ExecuteAsync(AgentToolExecutionContext c,JsonElement a,CancellationToken ct){var conversation=await db.WhatsAppConversations.FirstOrDefaultAsync(x=>x.Id==c.ConversationId,ct);if(conversation==null)return new(false,null,"Conversación no encontrada.","conversation_not_found");if(conversation.AttentionMode!=WhatsAppAttentionMode.Ai)return new(true,new{transferred=conversation.AttentionMode==WhatsAppAttentionMode.WaitingForHuman},null,"human_required",TransferredToHuman:true);var changed=attention.RequestHuman(conversation,null,clock.UtcNow);if(c.IncomingMessageId.HasValue){var incoming=await db.WhatsAppMessages.FirstOrDefaultAsync(x=>x.Id==c.IncomingMessageId,ct);if(incoming!=null){incoming.AiProcessingStatus=WhatsAppAiProcessingStatus.TransferredToHuman;incoming.AiProcessingError=a.GetProperty("reason").GetString()?.Trim();incoming.AiProcessedAt=clock.UtcNow;}}await db.SaveChangesAsync(ct);if(changed)await notifications.NotifyAttentionChangedAsync(conversation.BranchId,new SenorArroz.Application.Features.WhatsApp.DTOs.WhatsAppConversationDto{Id=conversation.Id,BranchId=conversation.BranchId,PhoneNumber=conversation.PhoneNumber,Status="open",AttentionMode="waitingForHuman",LastMessageAt=conversation.LastMessageAt,LastMessagePreview=conversation.LastMessagePreview,UnreadCount=conversation.UnreadCount,CreatedAt=conversation.CreatedAt,UpdatedAt=conversation.UpdatedAt,AttentionModeUpdatedAt=conversation.AttentionModeUpdatedAt},ct);var configured=await db.BranchAiSettings.AsNoTracking().Where(x=>x.BranchId==conversation.BranchId).Select(x=>x.TransferMessage).FirstOrDefaultAsync(ct);var text=string.IsNullOrWhiteSpace(configured)?"Un asesor continuará con tu atención.":configured.Trim();var dispatch=$"{c.ExecutionId??$"msg-{c.IncomingMessageId??0}"}:human-transfer";var sent=await sender.SendTransferTextAsync(conversation.Id,c.IncomingMessageId??0,dispatch,text,ct);return new(true,new{transferred=true,messageSent=sent.Success},null,"human_required","La conversación fue transferida.",TransferredToHuman:true,Warnings:sent.Success?null:[sent.Error??"No se pudo enviar el aviso de transferencia."]);}
}
